// mặc định component tạo ra ở nextJS là server component
// muốn dùng state hay hook phải khai báo 'use client;
"use client";
import{ useState } from "react";
import "./card.css";
import custom from "./custom.module.scss";
import clsx from "clsx";

export default function Card() {
  const [expanding, setExpanding] = useState(true);

  return <div className={clsx("card", { [custom.card]: expanding })}>Card</div>;
}
// ví dụ đây là 1 component của 1 thư viện có sẵn thì hãy override css của thư viện
// thêm class card trong file custom khi expanding = true